/**
 * Minh họa vì sao Java phù hợp cho backend:
 * kiểu dữ liệu rõ ràng, input bất biến, method nhỏ và output dự đoán được.
 *
 * Bài thực hành:
 * 1. Compile: javac BackendServiceExample.java
 * 2. Chạy:    java BackendServiceExample
 * 3. Đổi input để thấy validation bảo vệ boundary của service.
 */
public final class BackendServiceExample {
    public static void main(String[] args) {
        RegistrationRequest request = new RegistrationRequest("java-labs@example.com", "Java Labs");
        AccountSummary summary = register(request);
        System.out.println(summary.displayName() + " <" + summary.email() + ">");
    }

    /**
     * Method kiểu service: validate input, chuẩn hóa dữ liệu, rồi trả về kết quả ổn định.
     */
    private static AccountSummary register(RegistrationRequest request) {
        requireText(request.email(), "email");
        requireText(request.displayName(), "displayName");

        String normalizedEmail = request.email().trim().toLowerCase();
        String cleanDisplayName = request.displayName().trim();
        return new AccountSummary(normalizedEmail, cleanDisplayName);
    }

    private static void requireText(String value, String fieldName) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(fieldName + " must not be blank");
        }
    }

    /** Request object bất biến, phù hợp cho DTO nhập vào service. */
    record RegistrationRequest(String email, String displayName) {}

    /** Response object bất biến trả ra khỏi service boundary. */
    record AccountSummary(String email, String displayName) {}
}

/**
 * Công cụ nhỏ để hiểu JDK/JRE/JVM qua thông tin runtime.
 *
 * Chạy thử:
 *   javac JavaRuntimeInfo.java
 *   java JavaRuntimeInfo
 */
public final class JavaRuntimeInfo {
    public static void main(String[] args) {
        printProperty("Java version", "java.version");
        printProperty("JVM name", "java.vm.name");
        printProperty("JVM vendor", "java.vm.vendor");
        printProperty("Runtime name", "java.runtime.name");
        printProperty("Java home", "java.home");
    }

    /** In một runtime property theo format dễ đọc và nhất quán. */
    private static void printProperty(String label, String propertyName) {
        String value = System.getProperty(propertyName, "<unknown>");
        System.out.printf("%-14s : %s%n", label, value);
    }
}

/**
 * Compile và inspect class này để nối source code với bytecode.
 *
 * Lệnh thực hành:
 *   javac CompilationFlowDemo.java
 *   javap -c CompilationFlowDemo
 *   java CompilationFlowDemo
 */
public final class CompilationFlowDemo {
    public static void main(String[] args) {
        int total = sumInclusive(1, 5);
        System.out.println("Total = " + total);
    }

    /**
     * Tính tổng từ start tới end, bao gồm cả hai biên.
     * Method nhỏ giúp bytecode dễ đọc hơn khi inspect.
     */
    private static int sumInclusive(int start, int end) {
        int total = 0;
        for (int current = start; current <= end; current++) {
            total += current;
        }
        return total;
    }
}

/**
