import java.util.List;

public final class PrimitiveVsWrapperDemo {
    public static void main(String[] args) {
        int primitiveCount = 3;
        Integer wrapperCount = Integer.valueOf(primitiveCount);
        List<Integer> counts = List.of(wrapperCount, 10, 20);

        System.out.println("Primitive: " + primitiveCount);
        System.out.println("Wrapper list: " + counts);
    }
}

