/**
 * Java có static typing: compiler kiểm tra chữ ký method trước runtime.
 * Ví dụ này mô hình hóa một phép tính backend bằng input/output type rõ ràng.
 */
public final class StaticTypingDemo {
    public static void main(String[] args) {
        Money subtotal = new Money(100_00, "USD");
        Money total = addTax(subtotal, 8.25);
        System.out.println(total.currency() + " " + total.cents());
    }

    /** Trả về value mới thay vì mutate input ban đầu. */
    private static Money addTax(Money subtotal, double taxPercent) {
        long tax = Math.round(subtotal.cents() * taxPercent / 100.0);
        return new Money(subtotal.cents() + tax, subtotal.currency());
    }

    record Money(long cents, String currency) {}
}

